    "[[VIZ]]{\"type\":\"arrangement-row\",\"title\":\"Seating order, seats 1–5 (left to right)\",\"seats\":[\"Uma\",\"Sana\",\"Rohan\",\"Tarun\",\"Vikram\"]}[[/VIZ]]",
